mapper.select:
SELECT DISTINCT cp.post_id, cp.user_idx, u.nickname, cp.title, cp.content, cp.created_at, cpd.region, cpd.post_type, cpd.post_status, cpd.view_count, cpd.like_count, cpd.comment_count, cpd.updated_at, cpi.image_url AS thumb_url, cpq.is_solved, u.account_status FROM COMMUNITY_POST cp JOIN COMMUNITY_POST_DETAIL cpd ON cp.post_id = cpd.post_id LEFT JOIN USERS u ON cp.user_idx = u.user_idx LEFT JOIN COMMUNITY_POST_IMAGE cpi ON cp.post_id = cpi.post_id AND cpi.sort_order = 1 LEFT JOIN COMMUNITY_POST_TAG cpt ON cp.post_id = cpt.post_id LEFT JOIN COMMUNITY_TAG ct ON cpt.tag_id = ct.tag_id LEFT JOIN COMMUNITY_POST_QUESTION cpq ON cp.post_id = cpq.post_id WHERE cpd.post_status IN ('ACTIVE', 'DORMANT')
AND cpd.region = #{region}
AND cpd.post_type = #{type}
AND ( ct.tag_name LIKE CONCAT('%', #{keyword}, '%') OR cp.title LIKE CONCAT('%', #{keyword}, '%') OR cp.content LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY cpd.like_count DESC, cp.created_at DESC
ORDER BY cpd.view_count DESC, cp.created_at DESC
ORDER BY cp.created_at DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(DISTINCT cp.post_id) FROM COMMUNITY_POST cp JOIN COMMUNITY_POST_DETAIL cpd ON cp.post_id = cpd.post_id LEFT JOIN USERS u ON cp.user_idx = u.user_idx LEFT JOIN COMMUNITY_POST_TAG cpt ON cp.post_id = cpt.post_id LEFT JOIN COMMUNITY_TAG ct ON cpt.tag_id = ct.tag_id WHERE cpd.post_status IN ('ACTIVE', 'DORMANT')
AND cpd.region = #{region}
AND cpd.post_type = #{type}
AND ( ct.tag_name LIKE CONCAT('%', #{keyword}, '%') OR cp.title LIKE CONCAT('%', #{keyword}, '%') OR cp.content LIKE CONCAT('%', #{keyword}, '%') )

SELECT tip_category
FROM COMMUNITY_POST_TIP
WHERE post_id = #{postId}

SELECT is_solved
FROM COMMUNITY_POST_QUESTION
WHERE post_id = #{postId}

mapper.update:
UPDATE COMMUNITY_POST_DETAIL
SET view_count = view_count + 1
WHERE post_id = #{postId}

